for k, n_ in [('phuoc-loc', 'Phước Lộc'), ('nghia-hanh', 'Nghĩa Hành'), ('chop-non', 'Chóp Nón'), ('duy-xuyen', 'Duy Xuyên'), ('tan-rai', 'Tân Rai')]:
    NP(k, n_)
A('1965-0528-bagia', '1965-05-28', VH, 'Quảng Ngãi. The night of May 28 the forces of the Ba Gia campaign (western Sơn Tịnh) move to their hiding places: Regiment 1 of Military Region 5 (Battalions 40, 60, 90, with a support battalion), the independent Battalion 45, under Lê Hữu Trữ and Nguyễn Đình Trọng, in the main direction; Battalion 83 and two district companies, militia and guerrillas in the second, Battalion 83 pressed against the Nghĩa Hành district seat. Chu Huy Mân, commander and commissar of the Region, is the campaign\'s commander. Against them at Ba Gia the Saigon 1st Battalion, 51st Regiment, with Ranger Battalions 37 and 39 and the 2d Battalion of the 51st nearby.', 'III, 422–23', place='ba-gia', band_='night', names=['Chu Huy Mân', 'Lê Hữu Trữ', 'Nguyễn Đình Trọng'], also=OP, vis=True, check='the night\'s hour; the history gives the units\' order of battle in the preceding page, III, 422–23; the campaign\'s order is not dated.')
A('1965-0529-bagia', '1965-05-29', VH, 'Quảng Ngãi. May 29 the sappers of Regiment 1 with a Sơn Tịnh district platoon hit the Self-Defense men of Phước Lộc village; Saigon\'s guns at Ba Gia fire to help them and the company at Núi Tròn comes back to relieve them. Two companies of the 1st Battalion, 51st Regiment, under Capt. Nguyễn Văn Ngọc with two American advisers, come down from Gò Cao and are met at Diên Niên and Lộc Thọ by Battalion 90, hidden in Sơn Nam commune. At 9:50 a.m. the battalion is surrounded; at 10:45 it is finished. Two advisers killed, Ngọc and 217 taken; 270 killed and wounded in the five hours; 200 weapons and 4 trucks taken, by the history\'s count.', 'III, 423–25', place='ba-gia', time='09:50', tz='Asia/Ho_Chi_Minh', names=['Nguyễn Văn Ngọc'], also=OP, check='the clock is Saigon\'s; the American record has the first fight at Ba Gia, [[cal.1965-05-29.vietnam-operations]].')
A('1965-0529-nghiahanh', '1965-05-29', VH, 'Quảng Ngãi. May 29, in the second direction south of the Trà Khúc, Battalion 83 of the province surrounds and attacks the Nghĩa Hành district seat and threatens the Saigon troops at the Tư Nghĩa district seat, so that local forces can punish oppressors.', 'III, 425', place='nghia-hanh', also=OP)
A('1965-0530-bagia', '1965-05-30', VH, 'Quảng Ngãi. May 30 Saigon forms a task force from the 3d Marine Battalion, Ranger Battalions 37 and 39 and the 2d Battalion of the 51st Regiment, and sends it up from Sơn Tịnh with 20 GMC trucks and 12 M113s under hundreds of bombing sorties, at 9:30 a.m. At 1 p.m. the Ranger Battalion 39 reaches the foot of Chóp Nón hill, the 2d Battalion and the Marines Phước Lộc village. Regiment 1 meets them: Battalion 60 on Mả Tổ hill, Battalion 45 behind the Rangers, Battalion 40 on the west edge of Phước Lộc. Two hours: the Marine battalion mostly destroyed, the 2d Battalion hurt; by 7 p.m. the rest are drawn into Chóp Nón, hill 47, Mả Tổ and Phước Lộc.', 'III, 425–27', place='ba-gia', time='09:30', tz='Asia/Ho_Chi_Minh', also=OP, check='the clock is Saigon\'s; the American record has "May 30, three more battalions committed and beaten" ([[cal.1965-05-29.vietnam-operations]]).')
A('1965-0530-bagia-night', '1965-05-30', VH, 'Quảng Ngãi. The night of May 30–31 Regiment 1 goes on: Battalion 60 takes hill 47 and Mả Tổ from the 3d Marine Battalion and captures it whole; Battalion 40 fights trench by trench in Phước Lộc, where the 2d Battalion of the 51st Regiment makes a stand in the strategic hamlet\'s trenches, and the rest withdraw; Battalion 45 with artillery takes Chóp Nón by hand-to-hand fighting that ends at 3:30 a.m., May 31, destroying Ranger Battalion 31. In three days: four Saigon battalions hurt, 916 killed (four American advisers) and 65 taken, 200 weapons taken, by the history\'s count.', 'III, 427–29', place='ba-gia', band_='night', also=OP, check='the clock is Saigon\'s; the figures are the history\'s ("a combined task force" destroyed); the American Defense Department record quoted by the history, III, 429.')
A('1965-0530-batk83', '1965-05-30', VH, 'Quảng Ngãi. The night of May 30 part of Battalion 83 raids the Ranger Battalion 37 around the town on the Vệ river and drives it up to Hành Đức, Nghĩa Hành district, where the local forces hurt it more and hold it.', 'III, 429–30', place='nghia-hanh', band_='night', also=OP, check='the place of the raid is the town on the Vệ river (Quảng Ngãi town or Nghĩa Hành); the history\'s words are "around the town on the Vệ river".')
A('1965-06-ea-nu', '1965-06', VH, 'Central Highlands. In early June part of Regiment 12 raids the Ea Nu strongpoint, beats the relief and cuts Route 7 from Mlá to Ea Nu; the rest of the regiment fights on Route 19 and cuts it from Măng Giang to An Khê.', 'III, 431', when='June, early', place='gia-lai', also=OP, tags=['ok:fields-place'], check='the day; the history names no province.')
A('1965-06-route21', '1965-06', VH, 'Central Highlands. In June Regiment 10 goes deep on Route 21, stops the supply convoy of Saigon\'s II Corps, destroys the escort company and takes or burns over 100 tons of rice. Routes 19, 7 and 21 are cut at the same time.', 'III, 431', when='June', place='dak-lak', also=OP, tags=['ok:fields-place'], check='the day; the province of the road; the history names none.')
A('1965-06-duco', '1965-06', VH, 'Gia Lai. After the ambush on Route 19 west, Regiment 320 besieges the Đức Cơ special forces camp and ambushes the force sent to relieve it: 40 vehicles destroyed, by the history\'s count. The province\'s and districts\' local forces help the guerrillas and people break the strategic hamlets from Thanh An to Đức Cơ.', 'III, 432', when='June', place='duc-co', also=OP, check='the day; the history gives none; the American record has the Đức Cơ battle ([[cal.1965-06.vietnam-operations]], [[cal.1965-08-01.vietnam-operations]]).')
A('1965-06-tamky-hq', '1965-07', VH, 'Quảng Nam. In July the province\'s armed force destroys the field command post of the Saigon 2d Division in the middle of Tam Kỳ town and fights on the road from the An Tân bridge to the Ông Bộ bridge: hundreds of Saigon soldiers and many American advisers killed, by the history\'s count.', 'III, 433', when='July', place='tam-ky', also=OP, check='the day; the history puts it after the second Ba Gia fight of July 5.')
A('1965-0528-duyxuyen', '1965-05-28', VH, 'Quảng Đà. May 28 Battalion 1 of the province\'s local troops attacks and destroys two Civil Guard companies and seven Self-Defense platoons at Duy Xuyên.', 'III, 434', place='duy-xuyen', also=OP)
A('1965-06-tanrai', '1965-06', VH, 'Lâm Đồng. The province\'s local forces besiege and attack the Tân Rai commando camp and force the American special forces in it to flee.', 'III, 434', when='June', place='tan-rai', also=OP, check='the day; the history gives none, between acts of May 28 and June 27.')
C('cal.1965-05-29.vietnam-operations', 'III, 423–29 (May 28–31, 1965, the Ba Gia campaign of Regiment 1: the battle in three days)', 'B-D')
V('cal.1965-05-29.vietnam-operations', 'D', 'the Saigon side loses 916 killed (four American advisers) and 65 taken in three days of the campaign; Regiment 1 takes 200 weapons', 'III, 429')
